import { useState, type ChangeEvent } from 'react';
import { JxButton, JxInputField, JxStepper } from '@jinx-ui/react';

type RegistrationWizardData = {
  name: string;
  email: string;
  phone: string;
  city: string;
  street: string;
  postalCode: string;
};

type RegistrationWizardProps = {
  onSubmit: (data: RegistrationWizardData) => void;
};

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationWizardData>({
    name: '',
    email: '',
    phone: '',
    city: '',
    street: '',
    postalCode: '',
  });

  const isLastStep = step === steps.length - 1;

  const updateField = (field: keyof RegistrationWizardData) => (event: ChangeEvent<HTMLInputElement>) => {
    const nextValue = event.target.value;
    setData((prev) => ({ ...prev, [field]: nextValue }));
  };

  const handleBack = () => setStep((current) => Math.max(current - 1, 0));

  const handlePrimary = () => {
    if (isLastStep) {
      onSubmit(data);
      return;
    }
    setStep((current) => Math.min(current + 1, steps.length - 1));
  };

  return (
    <div>
      <JxStepper current={step} steps={steps} />
      {step === 0 ? (
        <div>
          <JxInputField label="Имя" required value={data.name} onChange={updateField('name')} />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={data.email}
            onChange={updateField('email')}
          />
          <JxInputField
