        <div>
          <JxInputField label="Город" required value={data.city} onChange={updateField('city')} />
          <JxInputField label="Улица и дом" required value={data.street} onChange={updateField('street')} />
          <JxInputField
            label="Почтовый индекс"
            required
            value={data.postalCode}
            onChange={updateField('postalCode')}
          />
        </div>
      ) : null}
      {step === 2 ? (
        <dl>
          <dt>Имя</dt>
          <dd>{data.name}</dd>
          <dt>Электронная почта</dt>
          <dd>{data.email}</dd>
          <dt>Телефон</dt>
          <dd>{data.phone}</dd>
          <dt>Город</dt>
          <dd>{data.city}</dd>
          <dt>Улица и дом</dt>
          <dd>{data.street}</dd>
          <dt>Почтовый индекс</dt>
          <dd>{data.postalCode}</dd>
        </dl>
      ) : null}
      <div style={{ display: 'flex', gap: 'var(--jx-gap, 8px)' }}>
